using System;
using System.Collections.Generic;
using System.Linq;

public enum Direction { North, East, South, West }

// A record: compared by value, printed nicely, and changed only by making copies.
public record GridPos(int X, int Y)
{
    public GridPos Move(Direction d, int steps = 1) => d switch
    {
        Direction.North => this with { Y = Y + steps },
        Direction.South => this with { Y = Y - steps },
        Direction.East => this with { X = X + steps },
        Direction.West => this with { X = X - steps },
        _ => throw new ArgumentOutOfRangeException(nameof(d))   // (Direction)9 compiles, so guard it
    };

    public int DistanceTo(GridPos other) => Math.Abs(X - other.X) + Math.Abs(Y - other.Y);
}

public static class Compass
{
    // The enum values are 0, 1, 2, 3 in order, so "next" is +1 wrapping round.
    public static Direction TurnRight(Direction d) => (Direction)(((int)d + 1) % 4);
}

