using System;
using System.Collections.Generic;
using System.Linq;

public enum Weather { Sunny, Rainy, Stormy, Dry }

public static class FarmAdvice
{
    public static string Advice(Weather w) => w switch
    {
        Weather.Sunny => "Good day to harvest",
        Weather.Rainy => "Plant the beans",
        Weather.Stormy => "Stay inside and check the drains",
        Weather.Dry => "Water the seedlings early",
        _ => throw new ArgumentOutOfRangeException(nameof(w))
    };

    public static Weather Parse(string text)
    {
        // TryParse with ignoreCase: true. IsDefined stops "7" sneaking in as a number.
        if (text != null && Enum.TryParse(text.Trim(), true, out Weather w) && Enum.IsDefined(w)) return w;
        throw new ArgumentException($"Unknown weather: {text}");
    }
}

