using System;
using System.Collections.Generic;
using System.Linq;

public class InsufficientFundsException : Exception
{
    public decimal Shortfall { get; }

    public InsufficientFundsException(decimal shortfall)
        : base($"Not enough money: short by {shortfall}")
    {
        Shortfall = shortfall;
    }
}

public class SavingsAccount
{
    public string Owner { get; }
    public decimal Balance { get; private set; }

    public SavingsAccount(string owner, decimal opening = 0)
    {
        Owner = owner;
        Balance = opening;
    }

    public void Deposit(decimal amount)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount));
        Balance += amount;
    }

    public void Withdraw(decimal amount)
    {
        if (amount <= 0) throw new ArgumentOutOfRangeException(nameof(amount));
        if (amount > Balance) throw new InsufficientFundsException(amount - Balance);
        Balance -= amount;
    }
}

public static class Teller
{
    public static int Attempts { get; private set; }

    public static string TryWithdraw(SavingsAccount account, decimal amount)
    {
        try
        {
            account.Withdraw(amount);
            return $"OK, balance {account.Balance}";
        }
        catch (InsufficientFundsException ex)       // the specific problem first
        {
            return $"Short by {ex.Shortfall}";
        }
        catch (ArgumentOutOfRangeException)
        {
            return "Bad amount";
        }
        finally
        {
            Attempts++;                              // runs whether it worked or not
        }
    }
}
